/* ── #25 统一日志（fail）：log.js 存在 + 归档命名格式/轮转判定单测（临时目录）+ LOG_DIR 单源 ── */
{
  const logMod = require('../lib/log');
  const pathsMod = require('../lib/paths');
  const os = require('node:os');
  let sub = 0, bad = 0;
  const t = (label, fn) => {
    sub++;
    try { fn(); } catch (e) { bad++; fail(25, `统一日志「${label}」：${e.message}`); }
  };
  const eq = (a, b) => { if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error(`期望 ${JSON.stringify(b)} 实际 ${JSON.stringify(a)}`); };

  t('LOG_DIR 单源：log.js 从 lib/paths.js 取日志目录（禁散落字面量）', () => {
    eq(typeof pathsMod.LOG_DIR, 'string');
    // V20261117014 ISSUE-2：LOG_DIR 可被 CHROMEUSE_LOG_DIR 覆盖（未设/空串=默认；相对路径按 SKILL_ROOT 基准）
    const logEnv = process.env.CHROMEUSE_LOG_DIR;
    const expectedLogDir = logEnv
      ? path.normalize(path.isAbsolute(logEnv) ? logEnv : path.join(pathsMod.SKILL_ROOT, logEnv))
      : path.join(pathsMod.SKILL_ROOT, 'log');
    eq(pathsMod.LOG_DIR, expectedLogDir);
    const src = read('lib/log.js');
    eq(src.includes('paths.LOG_DIR'), true);
    if (/path\.join\(__dirname, ?\.\., ?['"]log['"]\)/.test(src) || /['"]log['"]\s*\)/.test(src.replace(/chromeuse\.log/g, ''))) {
      throw new Error('log.js 疑似绕过 paths 单源自拼 log 目录');
    }
  });
  t('归档命名格式：chromeuse.<yyyyMMddTHHmmss>.log（omo-slim 风格）', () => {
    const name = `chromeuse.${logMod._internals.archiveStamp(new Date('2026-09-09T02:00:00'))}.log`;
    if (!/^chromeuse\.\d{8}T\d{6}\.log$/.test(name)) throw new Error(`归档名不匹配格式：${name}`);
  });
  t('日期轮转：过期日志（首行旧时间戳）→ 归档改名，今天文件不动（临时目录，零 skill 目录写入）', () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'chromeuse-selftest-log-'));
    try {
      const fake = path.join(tmp, 'chromeuse.log');
      fs.writeFileSync(fake, '[2026-08-01T00:00:00.000Z] [INFO] [t] 上周日志\n');
      const now = new Date();
      const archived = logMod._internals.rotateStale(fake, now);
      if (!archived || !/^chromeuse\.\d{8}T\d{6}\.log$/.test(path.basename(archived))) throw new Error(`归档改名异常：${archived}`);
      if (fs.existsSync(fake)) throw new Error('归档后旧文件仍在');
      if (fs.readdirSync(tmp).length !== 1) throw new Error('归档产物数量异常');
      // 今天文件：不轮转
      const fresh = path.join(tmp, 'chromeuse.log');
      fs.writeFileSync(fresh, `[${now.toISOString()}] [INFO] [t] 今天\n`);
      eq(logMod._internals.rotateStale(fresh, now), null);
      eq(logMod._internals.isFromToday(fresh, now), true);
      // mtime 兜底：无时间戳内容 + 刚创建 = 今天
      const raw = path.join(tmp, 'chromeuse.log');
      fs.writeFileSync(raw, '无时间戳内容\n');
      eq(logMod._internals.isFromToday(raw, now), true);
    } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
  });
  t('行格式与 debug 静默：buildLine 一行一条、err 压单行（时间戳=配置时区带偏移串，兼容 Z/±HH:mm 双结尾）', () => {
    const line = logMod._internals.buildLine('INFO', 't', '消息');
    if (!/^\[\d{4}-\d{2}-\d{2}T[\d:.]+(?:Z|[+-]\d{2}:\d{2})\] \[INFO\] \[t\] 消息$/.test(line)) throw new Error(`行格式不匹配：${line}`);
    const lineErr = logMod._internals.buildLine('ERROR', 't', '失败', new Error('boom\n  at f()'));
    if (lineErr.includes('\n')) throw new Error('err 未压成单行');
    if (!lineErr.includes('boom')) throw new Error('err 消息丢失');
  });
  t('插桩到位：各脚本统一走 lib/log（events.js 热路径禁 log）', () => {
    for (const f of ['tools/cdp.js', 'lib/flow-engine.js', 'lib/record.js', 'lib/collector.js', 'install.js']) {
      if (!read(f).includes("require('../lib/log')") && !read(f).includes("require('./log')") && !read(f).includes("require('./lib/log')")) {
        throw new Error(`${f} 未接入统一日志 lib/log.js`);
      }
    }
    eq(read('lib/events.js').includes("require('./log')"), false);
  });
  check(25, bad === 0, `统一日志组 ${bad}/${sub} 个用例失败`, `统一日志组 ${sub} 个用例全过（log.js+归档轮转+LOG_DIR 单源）`);
}

