    if (!src.includes("document.activeElement")) throw new Error('probe 目标须为 document.activeElement（insertText 真实落点）');
    if (!src.includes('text.slice(0, 20)')) throw new Error('缺 contains 首 20 字符裁剪（千字级全等在 ProseMirror normal form 下不可靠）');
    if (!src.includes('写后读断言失败')) throw new Error('缺重试告警文案');
    if (!src.includes('TYPE_VERIFY_FAILED')) throw new Error('缺独立错误码 TYPE_VERIFY_FAILED');
    if (!/attempt <= 3/.test(src)) throw new Error('缺 3 次重试循环');
