    const s = mkDepth2({ '166,41': null }, { midFrameNull: true }); // absOf 止于 innerFrame（midDoc fe=null）→ 查询点=166,41
    s.topDoc.__pointHits['166,41'] = s.outerFrame;
    const r = runVerify(s.topDoc, s.spec);
    eq(r, 'pass-hit', '部分集合时非成员 iframe→保守放行（不误判兄弟层）');
    // ⑤b 完整性对照：同部分集合但命中=成员帧 → 照常放行（成员检查不受完整性影响）
    const s2 = mkDepth2({ '166,41': null }, { midFrameNull: true });
