    if (!src.includes('await this.gateWait(clickTarget, gateBudget)')) throw new Error('click case 缺 gateWait 接线（须与点击同一描述符产物）');
    if (!src.includes('await this.centerClick(clickTarget, s.dbl ? 2 : 1')) throw new Error('centerClick 未消费提升产物（同描述符共享破坏）');
