  const risk = await run({ outDir: process.env.RISK_DIR, name: 'risk', maxChunk: 4600, format: 'png', dpr: 3, viewport: '1200x600' }, BIG);
  out.risk = { pngRisk: risk.m.pngRisk, status: risk.m.status, count: risk.m.sliceCount, notes: risk.m.notes };
