    eq(o.real.slices.map((s) => s.y), [0, 500, 1000], '实跑段起点');
    eq(o.real.slices.map((s) => s.via), ['A', 'A', 'A'], 'A 路径（几何精确）');
    eq(o.real.slices.map((s) => s.overlapPx), [0, 0, 0], 'overlap 默认 0');
