  const imgs = spec.map((s) => { const im = mkImg(s); im.loadsAt = s.loadsAt === undefined ? 1 : s.loadsAt; return im; });
  const documentObj = { images: imgs, documentElement: { scrollHeight: 1000 }, body: { scrollHeight: 1000 }, readyState: 'complete' };
