    eq([ur.contentOk, ur.afterDetail.length, ur.afterDetail[0].size, ur.localSizes[0]], [true, 2, 2, 2], '内容 size 校验通过（本地 2B = 浏览器读回 2B）');
    eq(c.sent.map((x) => x.method), ['Runtime.evaluate', 'Runtime.callFunctionOn', 'DOM.setFileInputFiles', 'Runtime.callFunctionOn', 'Runtime.releaseObject'], 'upload 方法序列');
    eq(c.sent[2].params.files, [f1, f2], 'DOM.setFileInputFiles files 透传');
    c = mkClient({ zeroSize: true });
