    for (const kind of ['text', 'table', 'attr', 'links', 'json']) {
      const spec = { kind, selector: kind === 'text' ? null : 'x', attr: kind === 'attr' ? 'href' : null, limit: 100 };
      const expr = ex.buildExtractExpr(spec);
      try { new Function(expr); } catch (e) { throw new Error(`${kind} 表达式语法非法：${e.message}`); }
    }
    const jsonExpr = ex.buildExtractExpr({ kind: 'json', selector: null, attr: null, limit: 100 });
