const perceive = require(DIR + '/lib/perceive');
const snapshot = require(DIR + '/lib/snapshot-diff');
const axNode = (o) => Object.assign({ properties: [] }, o);
const ROLE = (v) => ({ type: 'role', value: v });
const NAME = (v) => ({ type: 'name', value: v });
