    eq(Object.keys(meta.commands).filter((k) => meta.commands[k].jsonAllowed).length, 13, '--json 放行面 13（批 6 handoff +1）');
    ok(meta.commands.locator.flags.includes('--js-listeners') && meta.commands.locator.flags.includes('--cursor-pointer'), 'locator meta.flags 登记新旗标');
    ok(meta.commands.a11y.flags.includes('--mark-js'), 'a11y meta.flags 登记 --mark-js');
