    const iSec = idxOf(calls, 'Security.setIgnoreCertificateErrors');
    ok(iSec >= 0 && idxOf(calls, 'Page.navigate') > iSec, 'exec：Security 必须先于 Page.navigate');
    log = freshLog();
    r = runW(['new', '--insecure', 'http://fake/'], { CU119_LOG: log });
    eq(r.status, 0, `new --insecure exit：${r.stderr}`);
