    eq(r.status, 0, `screenshot --insecure 应正常执行（静默忽略）：${r.stderr}`);
    eq(secCalls(readLog(log)).length, 0, '不支持命令带 --insecure 时零 Security.* 调用');
    /* 审计：goto --insecure 恰好一行 security.ignore-certs（成功审计行另有一条，action 缺省=cmd） */
    const auditTd = path.join(tmp, 'audit-td');
    log = freshLog();
