    const lines = fs.readdirSync(auditDir).filter((f) => f.endsWith('.jsonl')).flatMap((f) => fs.readFileSync(path.join(auditDir, f), 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l)));
    const hit = lines.filter((e) => e.action === 'security.ignore-certs');
    eq(hit.length, 1, 'security.ignore-certs 审计恰一条');
    eq(hit[0].cmd, 'goto', '审计 cmd');
    eq(hit[0].code, null, '审计 code=null');
