  r.vars.big = new Array(51).fill(0);
  out.overBig = await code(() => r.step({ action: 'loop', over: 'big', count: 1, itemVar: 'x' }, 5000));
  out.sandbox = await code(() => r.step({ action: 'eval', expr: 'process.env' }, 5000));
  r.ev = async () => { throw new Error('evaluate 超时（3000ms）'); };
